export function posicionarVegetacao(fase, lado) {
  const dados = porFase[fase.id];
  if (!dados || dados[1] !== lado) return [];
  const [mundo,,pontos] = dados;
  return pontos.flatMap((ponto, indice) => {
    if (!ponto) return [];
    const [coluna,linha,canto] = ponto;
    if (fase.mapa[linha]?.[coluna] !== '.') return [];
    const [largura,altura,faixas] = pecas['w'+mundo+(indice ? '-flor' : '-vegetal')];
    const margem = lado === 48 ? 5 : 4;
    return [{
      coluna,linha,largura,altura,faixas,
      x: coluna*lado + (canto%2 ? lado-margem-largura : margem),
      y: linha*lado + (canto>=2 ? lado-margem-altura : margem)
    }];
  });
}

// Cede espaço às indicações de jogada e às personagens sem mudar os pontos escolhidos.
export function pintarVegetacao(pintar,fase,origemX,origemY,lado,protegida) {
  for (const planta of posicionarVegetacao(fase,lado)) {
    const {coluna,linha,x,y,faixas} = planta;
    if (protegida(coluna,linha)) continue;
    for (const [cor,dx,dy,w] of faixas) pintar(cor,origemX+x+dx,origemY+y+dy,w,1);
  }
}
